// The billing example's transpile output: developer-owned generated source and
// the tests that verify the runtime. Regenerated by `gradle generate`; separate
// from the compiler on purpose (Reference §22, "The extension framework").
plugins {
    kotlin("jvm")
}

group = "velle"

repositories {
    mavenCentral()
}

dependencies {
    implementation(project(":compiler"))
    // the generic SQLite backend the hydration spike app (velle/app) and the
    // store-backed tests run over
    implementation(project(":stores:sqlite"))
    // billing's amounts are `Money` (Reference §5, extension types): Alice's type
    // library, and Bob's binding so the SQLite store can hold it
    implementation(project(":extensions:finance"))
    runtimeOnly(project(":extensions:finance-sql"))
    testImplementation(kotlin("test"))
    testImplementation(project(":stores:postgres")) // and over PostgreSQL, when Docker is running
    testImplementation(testFixtures(project(":stores:postgres")))
}

tasks.test {
    useJUnitPlatform()
}

tasks.register<JavaExec>("runApp") {
    description = "Run the hydration spike app against a local SQLite db (billing.db)"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.app.BillingAppKt")
}

tasks.register<JavaExec>("generate") {
    description = "Regenerate the Billing typed surface, executable specs, and sequence diagrams from billing.velle"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.GenerateKt")
    // --diagrams opts this module into DIAGRAMS-Billing.md (mermaid sequence diagrams, OQ41)
    args("../billing.velle", "Billing", "--diagrams")
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_21)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}
